 if(saved?.privateContent?.version===7&&saved.modelContent?.layout===el.dataset.layout){Object.assign(cfg,saved.privateContent.design||{});if(['today','targets','activity','insights'].includes(saved.modelContent.screen)){state.page=saved.modelContent.screen;state.nav=state.page}}
 function remember(){if(!restoring)void persistWork().catch(()=>{});globalThis.openai?.setWidgetState?.({modelContent:{layout:el.dataset.layout,screen:state.page,primaryNavigation:state.nav,mapView:state.view,mapLayer:state.mapLayer,selectedMapSite:state.mapSelected,mapPreview:cfg.mapPreview,plannedItems:state.items.length,offlineScenario:cfg.offline},privateContent:{version:7,design:cfg}})?.catch(()=>{})}
 function dayLabel(day=state.day){return day==='tomorrow'?'tomorrow':'today'}
 function plannedItem(target,day=state.day){return state.items.find(i=>i.target===target&&i.day===day&&!i.cancelled&&!i.done)}
 function go(page,nav,patch={}){stashDraft();state.history.push({page:state.page,nav:state.nav,entity:state.entity,module:state.module,section:state.section,title:state.title,picking:state.picking,view:state.view,mapLayer:state.mapLayer,mapSelected:state.mapSelected,kind:state.kind,entityHistory:state.entityHistory,capturePicking:state.capturePicking,quickAdd:state.quickAdd,currentDraftId:state.currentDraftId});Object.assign(state,patch);state.page=page;if(page!=='targets')state.quickAdd=false;state.captureError='';if(nav)state.nav=nav;state.notice='';render();remember()}
 function back(){stashDraft();const prev=state.history.pop();if(prev)Object.assign(state,prev);else state.page=state.nav;state.captureError='';render();remember()}
 function link(name,sub,attrs='',icon='chevron-right'){return `<button type="button" class="day-listrow cursor-interaction" ${attrs}><span class="day-txt"><span class="day-name">${name}</span>${sub?`<span class="day-muted">${sub}</span>`:''}</span>${ic(icon)}</button>`}
