 function siteDistance(p){const a=mapData.sites.find(s=>s.id===(state.mapAnchor||'riverside')),b=mapData.sites.find(s=>s.id===(p.account||p.id));return a&&b&&globalThis.d3?d3.geoDistance(a.coordinates,b.coordinates)*6371:Infinity}
 function mapRecords(data){const records=data.filter(p=>state.mapLayer==='day'?activeDay().some(i=>i.target===p.id||find(i.target).account===(p.account||p.id)):state.mapLayer==='opportunity'?(p.id==='maya'||p.id==='riverside'||p.id==='eastside'):state.mapLayer==='nearby'?siteDistance(p)<=5:true);return state.mapLayer==='nearby'?records.sort((a,b)=>siteDistance(a)-siteDistance(b)):records}
 function mapFrame(records,mini=false){const ids=[...new Set(records.map(p=>p.account||p.id))];return `<div class="day-map-canvas ${mini?'day-map-mini':''}" data-geographic-map data-map-ids="${ids.join(',')}" ${mini?'data-mini="true"':''} aria-label="${mini?'Territory preview':'Public Manhattan facility locations'}"><svg class="day-map-svg" role="img" aria-label="Manhattan streets, parks and ${ids.length} sample facility locations"></svg><div class="day-map-pins"></div></div>`}
