 // Shared composed view, embedded into the standalone conversation concept.
function mapPanel(data) {
  const records = mapRecords(data);
  const sites = [...new Set(records.map(p => p.account || p.id))];
  if (!sites.includes(state.mapSelected)) state.mapSelected = sites[0] || '';
  const org = find(state.mapSelected);
  const record = records.find(p => (p.account || p.id) === state.mapSelected);
  const plannedItem = record && activeDay().find(i => i.target === record.id || (record.kind === 'hco' && find(i.target).account === record.id));
  const peopleHere = people.filter(p => p.account === state.mapSelected);
  const detail = record ? `
    <section class="day-map-detail" aria-live="polite">
      <div class="day-row"><span class="day-kicker">${plannedItem ? 'In your day' : state.mapLayer === 'opportunity' ? 'Sample opportunity' : 'Assigned target'}</span><span class="day-pill">${sites.indexOf(state.mapSelected) + 1}</span></div>
      <h2 style="margin-top:8px">${record.name}</h2>
      <p class="day-muted">${record.kind === 'hcp' ? record.sub + ' · ' + org.name : mapData.sites.find(s => s.id === org.id)?.address || org.city}</p>
      ${record.kind === 'hco' ? `<p class="day-muted" style="margin-top:8px">${peopleHere.length ? peopleHere.map(p => p.name).join(', ') : 'Open the account to review associated people.'}</p>` : ''}
      <p class="day-reason">${record.id === 'maya' || org.id === 'riverside' ? 'Sample reason · Follow-up due' : org.id === 'eastside' ? 'Sample reason · Account review opportunity' : record.reason}</p>
      <div class="day-actions">${button('Open brief', `data-profile="${record.id}"`)}${button(plannedItem ? 'Edit visit' : 'Add to day', `data-add="${plannedItem?.target || record.id}"`, 'primary')}</div>
    </section>` : `<div class="day-notice">${state.mapLayer === 'day' ? 'No matching visits in this day. Select targets to start planning.' : 'No matching targets. Adjust the search or layer.'}</div>`;
  return `
    <div class="day-map-layers" role="group" aria-label="Map layers">${[['all', 'Assigned'], ['day', 'My day'], ['opportunity', 'Opportunities'], ['nearby', 'Nearby']].map(([id, label]) => `<button type="button" class="cursor-interaction" data-map-layer="${id}" aria-pressed="${state.mapLayer === id}">${label}</button>`).join('')}</div>
    <div class="day-map-workspace">
      <div class="day-map-scene">${mapFrame(records)}${mapAttribution()}</div>
      <div class="day-map-context">
        <p class="day-caption" style="margin:8px 0">${sites.length} ${sites.length === 1 ? 'site' : 'sites'} · ${state.mapLayer === 'nearby' ? 'Within 5 km of ' + find(state.mapAnchor).name + ' · Straight-line distance' : 'Public facility locations · Sample assignments'} · No live location</p>
        ${detail}
        ${state.mapLayer === 'day' ? button('Review day & route', 'data-open="plan" class="day-full"', 'secondary') : ''}
      </div>
    </div>`;
}

 let mapObservers=[];
 function drawMaps(){mapObservers.forEach(o=>o.disconnect());mapObservers=[];el.querySelectorAll('[data-geographic-map]').forEach(container=>{const draw=()=>{if(!container.isConnected||!container.clientWidth)return;const svg=container.querySelector('svg'),pins=container.querySelector('.day-map-pins'),d=globalThis.d3;if(!d){svg.innerHTML='<text x="12" y="30" fill="currentColor">Map unavailable. Use List view.</text>';return}const w=container.clientWidth,h=container.clientHeight;const extent={type:'FeatureCollection',features:mapData.sites.map(s=>({type:'Feature',geometry:{type:'Point',coordinates:s.coordinates}}))};const projection=d.geoMercator().fitExtent([[38,30],[w-38,h-34]],extent);const path=d.geoPath(projection);svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=`<g class="day-map-land">${mapData.land.features.map(f=>`<path d="${path(f)||''}"></path>`).join('')}</g><g class="day-map-parks">${mapData.parks.features.map(f=>`<path d="${path(f)||''}"></path>`).join('')}</g><g class="day-map-roads">${mapData.roads.features.map(f=>`<path class="${f.properties.kind==='primary'||f.properties.kind==='secondary'?'day-major-road':''}" d="${path(f)||''}"></path>`).join('')}</g>`;const labels=mapData.labels.filter(l=>l.name==='Upper West Side'||l.name==='Upper East Side'||l.name==='Morningside Heights');const visibleLabels=labels.map(l=>({...l,point:projection(l.coordinates)})).filter(l=>l.point[0]>35&&l.point[0]<w-35&&l.point[1]>18&&l.point[1]<h-18);if(!container.dataset.mini&&cfg.textScale<=1.25)svg.innerHTML+=visibleLabels.map(l=>`<text class="day-map-place" x="${l.point[0]}" y="${l.point[1]}" text-anchor="middle">${esc(l.name)}</text>`).join('');const ids=container.dataset.mapIds.split(',').filter(Boolean);pins.innerHTML=ids.map((id,n)=>{const site=mapData.sites.find(s=>s.id===id);if(!site)return '';const [x,y]=projection(site.coordinates),selected=state.mapSelected===id&&!container.dataset.mini;return `<button type="button" class="day-map-pin cursor-interaction ${selected?'day-map-pin-selected':''}" style="left:${x}px;top:${y}px" aria-label="${site.name}" aria-pressed="${selected}" data-map-site="${id}" ${container.dataset.mini?'data-mini-site="true"':''}><span>${n+1}</span></button>`}).join('');pins.querySelectorAll('[data-map-site]').forEach(b=>b.onclick=()=>{if(b.dataset.miniSite)openHomeMap(b.dataset.mapSite);else{state.mapSelected=b.dataset.mapSite;render();remember()}})};const observer=new ResizeObserver(draw);observer.observe(container);mapObservers.push(observer);draw()})}
 function openHomeMap(id){go('targets','targets',{view:'map',kind:'hco',scope:'Assigned',query:'',mapSelected:id||'riverside',mapLayer:activeDay().length?'day':'all',picking:false})}
 function bindMaps(){el.querySelectorAll('[data-target-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.targetView;render();remember()});el.querySelectorAll('[data-map-home]').forEach(b=>b.onclick=()=>openHomeMap());el.querySelectorAll('[data-map-layer]').forEach(b=>b.onclick=()=>{if(b.dataset.mapLayer==='nearby')state.mapAnchor=state.mapSelected||'riverside';state.mapLayer=b.dataset.mapLayer;render();remember()});el.querySelector('[data-hide-mini]')?.addEventListener('click',()=>{cfg.mapPreview=false;render();remember()});el.querySelector('[data-show-mini]')?.addEventListener('click',()=>{cfg.mapPreview=true;render();remember()})}
 function targets(){const data=(state.kind==='hcp'?people:orgs).filter(p=>(p.name+' '+p.place+' '+p.sub).toLowerCase().includes(state.query.toLowerCase())).filter(p=>state.filter==='All targets'||p.reason==='Follow-up due');const filtered=mapRecords(data);return `${state.picking?backrow():''}<div class="day-kicker">${state.picking?'Build your day':'Your territory, connected'}</div><h1>${state.capturePicking?'Who did you speak with?':state.quickAdd?'Add a visit':state.picking?'Who will you see?':'Targets'}</h1><p class="day-muted">${state.scope==='Assigned'?'Your configured book of accounts and people.':'Sample discovery results beyond your assignments.'}</p><div class="day-search">${ic('search')}<input type="search" data-query placeholder="Name, specialty or organization" aria-label="Search targets" value="${esc(state.query)}"></div><div class="day-row"><div class="day-tabs" role="tablist" aria-label="Target type">${['hcp','hco'].map(k=>`<button type="button" class="cursor-interaction" role="tab" aria-selected="${state.kind===k}" data-kind="${k}">${k==='hcp'?'People':'Accounts'}</button>`).join('')}</div><button type="button" class="day-icon cursor-interaction" data-open="filters" aria-label="Filter targets">${ic('sliders-horizontal')}</button></div><div class="day-view-switch" role="group" aria-label="Target view">${[['list','List','list'],['map','Map','map']].map(([id,label,icon])=>`<button type="button" class="cursor-interaction" data-target-view="${id}" aria-pressed="${state.view===id}">${ic(icon)}${label}</button>`).join('')}</div><div data-results>${state.view==='map'?mapPanel(data):`${state.mapLayer!=='all'?`<p class="day-notice">${state.mapLayer==='day'?'My day':state.mapLayer==='nearby'?'Nearby sites':'Sample opportunities'} filter applied · <button type="button" class="day-link cursor-interaction" data-map-layer="all">Show all</button></p>`:''}${filtered.length?filtered.map(p=>accountRow(p,state.picking)).join(''):'<p class="day-notice">No matching sample targets.</p>'}`}</div>${state.picking?`<div class="day-card"><p class="day-muted" data-pick-count>${state.selected.length} selected · Times can stay flexible.</p>${button('Review my day '+ic('arrow-right'),'data-review-plan class="day-full"','primary')}</div>`:''}`}
 function sections(){const h=find(state.entity).kind==='hco',all=h?hcoSections:hcpSections;return `${backrow('Back to brief')}<div class="day-kicker">${find(state.entity).name}</div><h1>All sections</h1><p class="day-muted">A named destination for every profile area.</p><div class="day-section-grid">${all.map(x=>link(x,'',`data-section="${esc(x)}"`)).join('')}</div>`}
 function section(){const name=state.section,p=find(state.entity);const desc={'Publications':'Publication title, journal, authorship, date and source.','Clinical Trials':'Trial status, phase, sponsor and participation.','Payments':'General and research payments, companies, products and years.','Diagnosis':'Diagnosis scope, patients, claims and trends.','Procedure':'Procedure scope, volume, sites and trends.','Prescriptions':'Prescription activity, treatment and product scope.','Payer Mix':'Payer channels, coverage and reimbursement context.','Remittance':'Paid/allowed measures by payer and period.','Referrals':'Referrals in and out, sources and destinations.','HCP Graphs':'Professional and research relationship graphs.','SDOH':'Source-provided population context and definitions.','Financials':'Organization financial measures and their periods.','Quality':'Available organization quality and experience measures.','Notes':'Recorded discussions and follow-ups.'};return `${backrow('All sections')}<div class="day-kicker">${p.name}</div><h1>${esc(name)}</h1>${['HCPs & Executives','KOLs'].includes(name)?people.filter(x=>x.account===p.id).map(x=>accountRow(x)).join(''):`<div class="day-card"><span class="day-pill">Section preview</span><p class="day-preview">${desc[name]||'Source-linked records and details for this profile section.'}</p><p class="day-muted">This demo record has no loaded ${esc(name.toLowerCase())} dataset.</p></div>`}<div class="day-actions">${button('All sections','data-open="sections"')}${button('Back to brief',`data-profile="${p.id}"`,'primary')}</div>`}
 function freshItem(target){return{id:'v'+Date.now()+Math.floor(Math.random()*1000),target,mode:'flexible',time:'10:00',duration:30,type:'In-person visit',goal:'',confirmed:false,day:state.day,done:false,cancelled:false}}
 function itemEditor(){const i=state.editing||freshItem(state.entity),p=find(i.target);return `${backrow()}<div class="day-kicker">Plan for ${dayLabel(i.day)}</div><h1 style="font-size:calc(26px * var(--day-text-scale))">${p.name}</h1><p class="day-muted">${p.kind==='hcp'?p.place:p.city}</p><label class="day-field" for="visit-type-${el.dataset.layout}">Activity</label><select id="visit-type-${el.dataset.layout}" class="day-input" data-item-type>${['In-person visit','Phone call','Case observation','Email'].map(x=>`<option ${i.type===x?'selected':''}>${x}</option>`).join('')}</select><label class="day-field" for="timing-${el.dataset.layout}">Timing</label><select id="timing-${el.dataset.layout}" class="day-input" data-item-mode><option value="flexible" ${i.mode==='flexible'?'selected':''}>Flexible · Anytime ${dayLabel()}</option><option value="timed" ${i.mode==='timed'?'selected':''}>Planned time</option></select><div class="day-twocol"><div><label class="day-field" for="time-${el.dataset.layout}">Time, if planned</label><input id="time-${el.dataset.layout}" class="day-input" type="time" data-item-time value="${i.time}"></div><div><label class="day-field" for="duration-${el.dataset.layout}">Duration</label><select id="duration-${el.dataset.layout}" class="day-input" data-item-duration>${[15,30,45,60].map(n=>`<option value="${n}" ${i.duration===n?'selected':''}>${n} minutes</option>`).join('')}</select></div></div><label class="day-check" style="margin-top:10px"><input type="checkbox" data-item-confirmed ${i.confirmed?'checked':''}>This appointment is already confirmed</label><label class="day-field" for="goal-${el.dataset.layout}">Visit goal · optional</label><input id="goal-${el.dataset.layout}" class="day-input" data-item-goal placeholder="What would make this useful?" value="${esc(i.goal)}"><p class="day-caption" style="margin:13px 0">Choosing a time plans the visit. It does not book a meeting.</p>${button('Save to my day '+ic('arrow-right'),'data-save-item class="day-full"','primary')}`}
 function conflicts(){const timed=state.items.filter(i=>i.mode==='timed'&&!i.cancelled&&i.day===state.day);return timed.some((a,ix)=>timed.slice(ix+1).some(b=>{const at=+a.time.slice(0,2)*60 + +a.time.slice(3),bt=+b.time.slice(0,2)*60 + +b.time.slice(3);return at<bt+b.duration&&bt<at+a.duration}))}
 function plan(){const rows=state.items.filter(i=>i.day===state.day&&!i.cancelled);return `${backrow()}<div class="day-kicker">Fixed where needed. Flexible where useful.</div><h1>Your day, in order</h1><p class="day-muted">Planning ${dayLabel()}. Keep commitments in place. Adjust the visits around them.</p>${conflicts()?'<div class="day-notice day-warning" role="alert">Two planned times overlap. Edit a time before saving the day.</div>':''}${rows.length?rows.map(i=>timelineItem(i,true)).join(''):'<p class="day-notice">Choose a target to start your day.</p>'}<div class="day-card"><div class="day-row"><h3>Room between visits</h3><span class="day-pill">15 min buffer</span></div><p class="day-muted" style="margin-top:8px">Travel feasibility still needs a route calculation. Preview order is manual.</p></div><div class="day-actions">${button('Add targets','data-plan-start')}${button('Save day','data-save-day '+(conflicts()||!rows.length?'disabled':''),'primary')}</div>${button(ic('route')+' Review route','data-open="route" class="day-full"','secondary')}`}
 function route(){const rows=state.items.filter(i=>i.day===state.day&&!i.cancelled&&!i.done&&['In-person visit','Case observation'].includes(i.type)),groups=[];rows.forEach(i=>{const p=find(i.target),key=p.account||p.id;let g=groups.find(x=>x.id===key);if(!g){g={id:key,items:[]};groups.push(g)}g.items.push(p)});return `${backrow()}<div class="day-kicker">Travel between places</div><h1>Route review</h1><p class="day-muted">${groups.length} ${groups.length===1?'site':'sites'} · ${rows.length} in-person ${rows.length===1?'visit':'visits'}</p><div class="day-notice">Demo stop order · Live travel times and directions are unavailable.</div>${groups.map((g,n)=>`<div class="day-card"><span class="day-kicker">Stop ${n+1}</span><h2 style="margin-top:6px">${find(g.id).name}</h2><p class="day-muted">${g.items.map(p=>p.name).join(' · ')}</p></div>`).join('')}<p class="day-caption" style="margin:15px 0">People at the same site share a travel stop. Each keeps their own visit outcome.</p>${button('Edit my day','data-open="plan" class="day-full"','primary')}`}
 function task(){const t=state.tasks.find(x=>x.id===state.task);if(!t)return activity();return `${backrow()}<span class="day-kicker">An accepted next step</span><h1 style="font-size:calc(25px * var(--day-text-scale))">${esc(t.text)}</h1><p class="day-muted">${find(t.target).name}</p><div class="day-card"><div class="day-pair"><span>Owner</span><b>You</b></div><div class="day-pair"><span>Due</span><b>${t.due}</b></div><div class="day-pair"><span>Status</span><b>${t.done?'Completed':'Open'}</b></div></div>${button(t.done?'Mark open':'Mark completed','data-complete-task class="day-full"','primary')}${link('Source conversation','See the promise in context',`data-review-note="${t.note}"`,'message-square')}`}
 function modulePage(){const m=modules[state.module];if(m)return `${backrow()}<span class="day-kicker">Named destination · Surface preview</span><h1>${m.title}</h1><p class="day-lead">${m.sub}</p>${m.rows.map(([n,s,id])=>link(n,s,`data-module="${id}"`)).join('')}<p class="day-caption" style="margin-top:18px">This destination is mapped in the audit. Live datasets and service actions are not connected in this concept.</p>`;return `${backrow()}<span class="day-kicker">Surface preview</span><h1>${esc(state.title||state.module.replace(/([a-z])([A-Z])/g,'$1 $2'))}</h1><div class="day-card"><h2>Ready for the detailed design</h2><p class="day-muted" style="margin-top:10px">This destination is included in the surface-area inventory. Its data, permissions and action states will follow the existing product contracts.</p></div>${button('Back to workspace','data-nav="insights" class="day-full"','primary')}`}
 function ask(){return `${backrow()}<span class="day-kicker">${state.askEntity?find(state.askEntity).name:'Your book'}</span><h1>Ask a question</h1><label class="day-field" for="ask-${el.dataset.layout}">What would you like to understand?</label><textarea id="ask-${el.dataset.layout}" class="day-input" data-question placeholder="Which accounts match my current procedure scope?"></textarea><p class="day-caption" style="margin:12px 0">No AI response is generated in this preview.</p>${button('Preview question','data-ask class="day-full"','primary')}<p class="day-notice" data-answer hidden></p>`}
 function workspace(){return `${backrow()}<span class="day-kicker">Your configured workspace</span><h1>Field Pro</h1><label class="day-field" for="view-${el.dataset.layout}">Sales view · preview label</label><select id="view-${el.dataset.layout}" class="day-input" data-team>${['Capital Sales','Clinical Sales','HEMA','Sales Enablement'].map(t=>`<option ${state.team===t?'selected':''}>${t}</option>`).join('')}</select><p class="day-caption" style="margin:10px 0">Your team assigns access and targets. This selector previews the label only.</p><h2 class="day-section-heading">Sample rep workspace</h2><p class="day-caption">${esc(state.workspace.repId)} · Local browser isolation only.</p><div class="day-actions">${button('Rep One','data-switch-workspace="demo-rep"')}${button('Rep Two','data-switch-workspace="demo-rep-2"')}</div>${link('My targets','Configured accounts and people','data-nav="targets"','users')}${link('Lists & territories','Scope, membership and import review','data-module="collections"','map-pin')}${link('Team','Authorized manager entry','data-module="team"','users-round')}${link('Administration','Authorized setup, access and usage','data-module="workspaceadmin"','settings-2')}${link('Saved work','Preview queue and CRM status','data-open="sync"','cloud')}${link('CRM','Source-specific integration availability','data-open="crm"','refresh-cw')}`}
 function filters(){return `${backrow('Back to targets')}<h1>Filter targets</h1><label class="day-field" for="filter-${el.dataset.layout}">Show</label><select id="filter-${el.dataset.layout}" class="day-input" data-filter><option ${state.filter==='All targets'?'selected':''}>All targets</option><option ${state.filter==='Follow-up due'?'selected':''}>Follow-up due</option></select><div class="day-section-heading">${link('Search scope',state.scope,'data-scope','users')}${link('Lists & territories','Scope and membership','data-module="collections"','map-pin')}</div>${button('Show results','data-back class="day-full"','primary')}`}
 function render(){el.style.setProperty('--day-text-scale',cfg.textScale);el.style.setProperty('--day-device-width',({'Small phone':'320px','Standard phone':'390px','Large phone':'430px','Wide landscape':'840px'}[cfg.device]||(el.dataset.layout==='focus'?'840px':'430px')));el.dataset.textScale=cfg.textScale;el.toggleAttribute('data-large-type',cfg.textScale>1.25);el.style.setProperty('--day-radius',cfg.radius+'px');el.style.setProperty('--day-gap',cfg.spacing+'px');let content='';switch(state.page){case'today':content=today();break;case'targets':content=targets();break;case'profile':content=profile();break;case'recovery':content=recovery();break;case'booking':content=booking();break;case'prep':content=prep();break;case'materials':content=materials();break;case'sections':content=sections();break;case'section':content=section();break;case'item':content=itemEditor();break;case'plan':content=plan();break;case'route':content=route();break;case'change':content=change();break;case'capture':content=capture();break;case'activity':content=activity();break;case'review':content=review();break;case'task':content=task();break;case'sync':content=sync();break;case'insights':content=insights();break;case'module':content=modulePage();break;case'workspace':content=workspace();break;case'filters':content=filters();break;case'ask':content=ask();break;case'contact':content=`${backrow()}<h1>Contact</h1><p class="day-lead">${find(state.entity).name}</p><div class="day-card"><p class="day-muted">No verified phone or email is loaded for this demo record.</p></div>`;break;case'crm':content=`${backrow()}<h1>CRM</h1><div class="day-card"><h2>Check the connected source</h2><p class="day-preview">Field Pro push is disabled in the reviewed implementation. Insights has a separate company-gated sync flow.</p><p class="day-muted">No CRM action is performed by this preview.</p></div>${button('Review saved work','data-open="sync" class="day-full"','primary')}`;break;default:content=today()}
 el.innerHTML=`<header class="day-chrome"><div class="day-brand">docnexus<span class="day-dot"></span><small>Field Pro</small></div><button type="button" class="day-icon cursor-interaction" data-search-global aria-label="Search people and accounts">${ic('search')}</button><button type="button" class="day-icon cursor-interaction" data-open="workspace" aria-label="Workspace and settings">${ic('circle-user-round')}</button></header><main class="day-main" ${cfg.textScale>1.25?'data-large-text="true"':''}>${recordingBanner()}${content}${foot()}</main><nav class="day-nav" aria-label="Primary navigation">${[['today','Today','calendar-days'],['targets','Targets','users'],['activity','Activity','notebook-pen'],['insights','Insights','sparkles']].map(([v,l,i])=>`<button type="button" class="cursor-interaction" data-nav="${v}" ${state.nav===v?'aria-current="page"':''}>${ic(i)}${l}</button>`).join('')}</nav>`;el.querySelectorAll('h1').forEach(h=>h.style.fontFamily=cfg.serif?'Georgia,serif':'Arial,Helvetica,sans-serif');if(cfg.textScale>1.25)el.querySelectorAll('select').forEach(select=>{const full=document.createElement('p');full.className='day-current-selection';full.textContent='Selected: '+(select.selectedOptions[0]?.textContent||'None');select.after(full)});bind();bindPriorityFlows();bindMaps();bindCaptureUI();bindMockFlows();bindExperience();globalThis.lucide?.createIcons({attrs:{width:18,height:18}});drawMaps();if(!restoring&&lastRenderedPage&&lastRenderedPage!==state.page&&!el.closest('[data-variant]')?.hidden)el.scrollIntoView({block:'start'});lastRenderedPage=state.page}
 function bookingLabel(item){return item?.confirmed?'Confirmed':({'request-draft':'Request draft','reschedule-needed':'Needs rescheduling',requested:'Awaiting mock response',declined:'Declined',cancelled:'Cancelled'}[item?.bookingStatus]||(item?.mode==='timed'?'Planned time':'Flexible'))}
 function pendingGaps(day=state.day){return state.items.filter(i=>i.day===day&&i.cancelled&&state.gaps.includes(i.id))}
 function closeGap(id){state.gaps=state.gaps.filter(x=>x!==id);const next=pendingGaps()[0];state.gap=next?{visitId:next.id}:null}
 function shortText(text){return String(text||'').length>160?String(text).slice(0,157)+'…':String(text||'')}
 function contextNote(id){return state.notes.find(n=>!n.deletedAt&&(n.target===id||n.source===id||n.attendees?.includes(id)))}
 function openPrep(id){go('prep',null,{entity:id})}
 function sortTimedAppointments(){
  for(const day of ['today','tomorrow']){
   const positions=state.items.map((item,index)=>({item,index})).filter(({item})=>item.day===day&&item.mode==='timed'&&!item.cancelled&&!item.done);
   const timed=positions.map(x=>x.item).sort((a,b)=>a.time.localeCompare(b.time));
   positions.forEach((x,index)=>state.items[x.index]=timed[index]);
  }
 }
 function openBooking(id,itemId){const item=state.items.find(i=>i.id===itemId)||plannedItem(id);go('booking',null,{entity:id,booking:{...(item||freshItem(id)),mode:'timed'},bookingError:''})}
 function change(){
  const item=state.items.find(i=>i.id===state.changing);if(!item)return today();
  return `${backrow()}<span class="day-kicker">${find(item.target).name}</span><h1>Plans changed?</h1><p class="day-muted">${dayLabel(item.day)} · ${item.mode==='timed'?esc(item.time):'Flexible'} · ${item.duration} min</p>${link('Doctor cancelled · find alternatives','Keep the rest of your day in place.','data-doctor-cancel','calendar-x')}${link('Change appointment','Adjust the time or confirmation.',`data-book="${item.target}" data-book-item="${item.id}"`,'calendar-clock')}${item.day==='today'?link('Move to tomorrow','Keep this visit and its goal.','data-reschedule','calendar-arrow-up'):''}${link('Skip this visit','Leave the time open and keep the target.','data-skip','circle-minus')}<p class="day-caption day-section-heading">Changes here update the sample plan. They do not send a cancellation or contact anyone.</p>`;
 }
 function materials(){
  return `${backrow('Back to meeting prep')}<span class="day-kicker">${find(state.entity).name}</span><h1>What will you need?</h1><p class="day-muted">Keep the evidence specific to this meeting.</p>${[['Account report','Account performance and opportunity'],['Procedure mix report','Relevant procedure activity'],['Insight brief','Reviewed conversation themes and follow-ups']].map(([name,sub])=>link(name,sub,`data-add-material="${name}"`,'file-text')).join('')}<p class="day-caption day-section-heading">Creates an illustrative demo brief for this meeting. No live account dataset is queried.</p>`;
 }
 function bindPriorityFlows(){
  el.querySelectorAll('[data-prep]').forEach(b=>b.onclick=()=>openPrep(b.dataset.prep));
  el.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>openBooking(b.dataset.book,b.dataset.bookItem));
  el.querySelector('[data-doctor-cancel]')?.addEventListener('click',()=>{const i=state.items.find(x=>x.id===state.changing);i.cancelled=true;if(!state.gaps.includes(i.id))state.gaps.push(i.id);state.gap={visitId:i.id};go('recovery','today',{recoveryMode:'visit'})});
  el.querySelectorAll('[data-recovery-mode]').forEach(b=>b.onclick=()=>{state.recoveryMode=b.dataset.recoveryMode;render()});
  el.querySelectorAll('[data-replace]').forEach(b=>b.onclick=()=>{
   const old=state.items.find(i=>i.id===state.gap?.visitId);if(!old?.cancelled)return;
   const replacement={...freshItem(b.dataset.replace),day:old.day,mode:old.mode,time:old.time,duration:old.duration,type:state.recoveryMode==='call'?'Phone call':'In-person visit',goal:'',confirmed:false,replacesVisitId:old.id};
   state.items.splice(state.items.indexOf(old)+1,0,replacement);state.day=old.day;closeGap(old.id);state.page='today';state.nav='today';state.history=[];state.notice=state.recoveryMode==='call'?'Call planned. Confirm availability before calling.':'Replacement planned. Confirm availability before travelling.';render();remember();
  });
  el.querySelectorAll('[data-leave-gap]').forEach(b=>b.onclick=()=>{closeGap(state.gap?.visitId);state.page='today';state.nav='today';state.history=[];state.notice='The slot stays open. Your other appointments are unchanged.';render();remember()});
  el.querySelector('[data-undo-cancel]')?.addEventListener('click',()=>{const i=state.items.find(x=>x.id===state.gap?.visitId);if(i)i.cancelled=false;closeGap(i?.id);state.page='today';state.nav='today';state.history=[];render();remember()});
  el.querySelectorAll('[data-save-booking]').forEach(b=>b.onclick=()=>{
   const i={...state.booking,day:el.querySelector('[data-book-day]').value,time:el.querySelector('[data-book-time]').value,duration:+el.querySelector('[data-book-duration]').value,goal:el.querySelector('[data-book-goal]').value,confirmed:el.querySelector('[data-book-confirmed]').checked,mode:'timed'};
   if(!i.time){state.bookingError='Choose a time.';render();return}
   const start=+i.time.slice(0,2)*60 + +i.time.slice(3);
   const overlap=state.items.some(x=>x.id!==i.id&&x.day===i.day&&!x.cancelled&&!x.done&&x.mode==='timed'&&start<(+x.time.slice(0,2)*60 + +x.time.slice(3))+x.duration&&(+x.time.slice(0,2)*60 + +x.time.slice(3))<start+i.duration);
   if(overlap){state.bookingError='This overlaps another appointment. Choose another time.';state.booking=i;render();return}
   if(start+i.duration>1440){state.bookingError='Choose a time that ends within this day.';state.booking=i;render();return}
   delete i.requestId;delete i.responseDue;delete i.providerVersion;delete i.providerEvents;i.confirmationSource=i.confirmed?'Rep marked confirmed':'';i.bookingStatus=b.dataset.saveBooking==='draft'?'request-draft':'planned';if(i.bookingStatus==='request-draft')i.confirmed=false;
   const existing=state.items.findIndex(x=>x.id===i.id);if(existing<0)state.items.push(i);else state.items[existing]=i;
   sortTimedAppointments();state.booking=i;state.bookingError='';state.day=i.day;
   if(i.bookingStatus==='request-draft'){render();remember()}else{state.page='prep';state.notice='';render();remember()}
  });
  el.querySelectorAll('[data-add-material]').forEach(b=>b.onclick=()=>{if(!state.materials.some(m=>m.target===state.entity&&m.name===b.dataset.addMaterial))state.materials.push({id:'m'+Date.now(),target:state.entity,name:b.dataset.addMaterial});state.page='prep';render();remember()});
  el.querySelectorAll('[data-remove-material]').forEach(b=>b.onclick=()=>{state.materials=state.materials.filter(m=>m.id!==b.dataset.removeMaterial);render();remember()});
  for(const [attribute,key] of [['data-book-day','day'],['data-book-time','time'],['data-book-duration','duration'],['data-book-goal','goal'],['data-book-confirmed','confirmed']]){
   const field=el.querySelector('['+attribute+']');
   field?.addEventListener('input',()=>{
    const value=key==='confirmed'?field.checked:key==='duration'?+field.value:field.value;
    if(['day','time','duration'].includes(key)&&state.booking[key]!==value){state.booking.confirmed=false;el.querySelector('[data-book-confirmed]').checked=false}
    state.booking[key]=value;
   });
  }
 }

 /* BEGIN_CAPTURE_UI */
 // This file is bundled inside each responsive workspace by build-demo.py.
 function workspaceKey(){return Model.scopeKey(state.workspace)}
 function activeDraft(){return state.drafts[state.currentDraftId]}
 function storageLabel(){if(!deviceStore.persistent)return 'Preview memory only · Refresh clears this work';return state.storageError?'Not saved · '+state.storageError:state.storageStatus==='saving'?'Saving on this device…':'Saved on this device'}
 function updateStorageLabel(){el.querySelectorAll('[data-device-status]').forEach(x=>x.textContent=storageLabel())}
 function persistWork(){
  const scope=workspaceKey(),snapshot=Model.clone(state);state.storageStatus='saving';updateStorageLabel();
  const operation=persistenceQueue.catch(()=>{}).then(()=>{
   if(state.scenario==='storage-full')throw new Error('Device storage is full. Keep this page open or download the audio.');
   return deviceStore.save(scope,snapshot);
  });
  persistenceQueue=operation;
  operation.then(()=>{if(scope===workspaceKey()){state.storageStatus='saved';state.storageError='';updateStorageLabel()}},error=>{if(scope===workspaceKey()){state.storageStatus='failed';state.storageError=error.message;updateStorageLabel()}});
  return operation;
 }
 function stashDraft(){const d=activeDraft();if(state.page==='capture'&&d){d.updatedAt=Date.now();void persistWork().catch(()=>{})}}
 function beginCapture(source,draftId,visitId){
  stashDraft();let d=state.drafts[draftId];
  const visit=state.items.find(i=>i.id===visitId)||plannedItem(source);
  if(!d&&visit)d=Object.values(state.drafts).find(x=>x.visitId===visit.id&&!x.editingNote);
  if(!d){d=Model.makeDraft({source,visitId:visit?.id||null,day:visit?.day||state.day,attendees:find(source).kind==='hcp'?[source]:[]});state.drafts[d.id]=d}
  go('capture',null,{entity:d.source,currentDraftId:d.id,capturePicking:false,captureError:''});
 }
 async function logOutcome(outcome){
  if(state.captureBusy)return;const d=activeDraft();if(!d)return;
  if(['recording','save-failed','interrupted'].includes(recorder.current()?.status)){state.captureError='Stop and save the recording before logging the outcome.';render();return}
  const before=Model.clone(state),draftId=d.id;state.captureBusy=true;
  try{
   const previousVisit=Model.clone(state.items.find(i=>i.id===d.visitId)||null);
   const note=Model.commit(state,draftId,outcome);
   state.lastUndo=d.editingNote?null:{noteId:note.id,draft:Model.clone(d),previousVisit};
   state.currentDraftId=null;state.captureError='';state.page='activity';state.nav='activity';state.history=[];state.notice='Outcome logged. You can continue your day.';
   await persistWork();state.captureBusy=false;render();remember();
  }catch(error){Object.assign(state,before);state.captureBusy=false;state.captureError=error.message;state.storageError=error.message;render()}
 }
 function capture(){
  const d=activeDraft();if(!d)return `${backrow()}<h1>No open draft</h1>${button('Choose a person','data-new-capture','primary')}`;
  const p=find(d.source),recording=recorder.current(),isRecording=recording?.draftId===d.id&&['recording','interrupted','save-failed'].includes(recording.status);
  return `${backrow()}<span class="day-kicker">${p.name} · ${dayLabel(d.day)}</span><h1>Log visit</h1><p class="day-muted">${p.kind==='hcp'?p.place:p.city}</p>${state.captureError?`<p role="alert" class="day-notice day-warning">${esc(state.captureError)}</p>`:''}<p class="day-caption" role="status" data-device-status>${esc(storageLabel())}</p><details class="day-capture-context" ${!d.attendees.length?'open':''}><summary>People & language · ${d.attendees.length} selected</summary>${people.map(person=>`<label class="day-check"><input type="checkbox" data-capture-attendee="${person.id}" ${d.attendees.includes(person.id)?'checked':''}>${person.name} · ${person.place}</label>`).join('')}<label class="day-field" for="language-${el.dataset.layout}">Recording language</label><select class="day-input" id="language-${el.dataset.layout}" data-capture-language>${['English','Hindi','Spanish','Other / mixed'].map(l=>`<option ${d.language===l?'selected':''}>${l}</option>`).join('')}</select></details><label class="day-field" for="capture-note-${el.dataset.layout}">Note · optional</label><textarea class="day-input" id="capture-note-${el.dataset.layout}" data-capture-note placeholder="What happened or what should you remember?">${esc(d.note)}</textarea><div class="day-actions">${button(d.intent==='meeting'?'Meeting recording':'Voice memo','data-capture-voice')}${button('Add file','data-open-file')}</div><input type="file" data-capture-file accept="audio/*,video/*,text/plain" hidden>${d.showVoice?`<div class="day-card"><h2>${d.intent==='meeting'?'Record the meeting':'Add a voice memo'}</h2><label class="day-field" for="intent-${el.dataset.layout}">Recording purpose</label><select class="day-input" id="intent-${el.dataset.layout}" data-capture-intent><option value="voice" ${d.intent!=='meeting'?'selected':''}>My post-visit voice memo</option><option value="meeting" ${d.intent==='meeting'?'selected':''}>Live meeting recording</option></select>${d.intent==='meeting'?'<p class="day-caption">Start only when recording is permitted for this meeting.</p>':''}<p class="day-muted" data-record-status>${recording?.draftId===d.id?esc(recording.status)+' · '+Math.round(recording.bytes/1024)+' KB committed on device':'Demo mode uses a sample tone; its transcript is mocked.'}</p><div class="day-actions">${isRecording?button('Stop & save audio','data-record-stop','primary'):button('Start sample recording','data-record-start="sample"','primary')}${!isRecording?button('Use my microphone','data-record-start="microphone"'):button('Interrupt sample','data-record-interrupt')}</div>${recording?.status==='save-failed'?button('Retry device save','data-record-retry'):''}</div>`:''}${d.mediaIds.map(id=>`<div class="day-material"><span>Saved attachment</span><audio controls preload="none" data-audio-asset="${id}"></audio>${button('Download original',`data-download-asset="${id}"`,'link')}</div>`).join('')}<details class="day-capture-context"><summary>Follow-up · optional</summary>${d.attendees.length>1?`<label class="day-field" for="follow-target-${el.dataset.layout}">Follow-up for</label><select id="follow-target-${el.dataset.layout}" class="day-input" data-capture-follow-target>${d.attendees.map(id=>`<option value="${id}" ${d.followTarget===id?'selected':''}>${find(id).name}</option>`).join('')}</select>`:''}<label class="day-field" for="capture-follow-${el.dataset.layout}">Promise or next step</label><input class="day-input" id="capture-follow-${el.dataset.layout}" data-capture-follow value="${esc(d.follow)}"><label class="day-field" for="capture-due-${el.dataset.layout}">Due date</label><input type="date" class="day-input" id="capture-due-${el.dataset.layout}" data-capture-due value="${d.due}"></details><h2 class="day-section-heading">What was the outcome?</h2><p class="day-caption">Choose the actual outcome to log this visit. Notes and audio are optional.</p><div class="day-outcomes">${[['Met','Met'],['Attempted','Not met'],['Rescheduled','Needs rescheduling']].map(([value,label])=>button(label,`data-log-outcome="${value}" ${state.captureBusy?'disabled':''}`,'secondary')).join('')}</div>`;
 }
 function conversationTitle(n){return (n.attendees||[n.target]).map(id=>find(id).name).join(', ')}
 function processingLabel(n){return n.processing==='failed'?'Processing failed · Original retained':n.processing==='ready'?(n.originalAudioIds?.length?'Demo transcript ready':'Summary ready'):n.processing==='transcribing'?'Demo transcription in progress':n.processing==='analyzing'?'Demo insights in progress':n.processing==='queued'?'Queued for demo processing':'Outcome recorded'}
 function activity(){
  const kind=state.activityFilter||'all',query=state.activityQuery||'';
  const namedMatches=state.notes.filter(n=>conversationTitle(n).toLocaleLowerCase().includes(query.toLocaleLowerCase()));
  const result=Model.search(state,query,kind),notes=state.notes.filter(n=>(result.includes(n)||namedMatches.includes(n))&&(kind==='trash'?!!n.deletedAt:!n.deletedAt)&&(kind!=='audio'||n.originalAudioIds?.length));
  const scoped=notes.filter(n=>!state.entityHistory||n.source===state.entityHistory||n.attendees?.includes(state.entityHistory)||n.attendees?.some(id=>find(id).account===state.entityHistory));
  const pendingSuggestions=state.notes.filter(n=>!n.deletedAt&&n.suggestions?.some(s=>!s.accepted&&!s.dismissed));const drafts=Object.values(state.drafts),failed=state.notes.filter(n=>!n.deletedAt&&n.processing==='failed');
  return `<h1>Activity</h1><div class="day-actions">${button('Log a visit','data-new-capture','primary')}${button('Saved work','data-open="sync"')}</div>${state.notice?`<p class="day-notice" role="status">${esc(state.notice)}${state.lastUndo?button('Undo last outcome','data-undo-outcome','link'):''}</p>`:''}${drafts.length||failed.length||pendingSuggestions.length?`<details class="day-capture-context" open><summary>Finish remaining work · ${drafts.length+failed.length+pendingSuggestions.length}</summary>${drafts.map(d=>link('Resume · '+find(d.source).name,dayLabel(d.day)+' · '+(d.mediaIds.length?'Audio saved':'Draft note'),`data-capture="${d.source}" data-draft="${d.id}"`,'notebook-pen')).join('')}${failed.map(n=>link(conversationTitle(n),'Processing failed · Original retained',`data-review-note="${n.id}"`,'triangle-alert')).join('')}${pendingSuggestions.map(n=>link(conversationTitle(n),'Review suggested next steps',`data-review-note="${n.id}"`,'list-checks')).join('')}</details>`:''}<label class="day-field" for="conversation-search-${el.dataset.layout}">Search conversations</label><input type="search" class="day-input" id="conversation-search-${el.dataset.layout}" data-conversation-query value="${esc(query)}" placeholder="Person, phrase, date or original words"><div class="day-view-switch" role="group" aria-label="Conversation filter">${[['all','Recent'],['audio','With audio'],['trash','Trash']].map(([id,name])=>button(name,`data-activity-filter="${id}" aria-pressed="${kind===id}"`,'link')).join('')}</div>${scoped.length?scoped.map(n=>`<button type="button" class="day-conversation-row cursor-interaction" data-review-note="${n.id}" aria-label="Open conversation with ${esc(conversationTitle(n))}"><span class="day-row"><span class="day-name">${esc(conversationTitle(n))}</span>${ic('chevron-right')}</span><span class="day-muted">${n.outcome} · ${n.meetingDate||dayLabel(n.day)}</span><span class="day-history-preview">${esc(shortText(n.correctedTranscript||n.text||n.transcriptOriginal||'Outcome recorded.'))}</span><span class="day-caption">${n.processing==='ready'?'':processingLabel(n)}</span></button>${n.deletedAt?button('Restore',`data-restore-note="${n.id}"`,'link'):''}`).join(''):'<p class="day-notice">No matching conversations.</p>'}<h2 class="day-section-heading">Follow-ups</h2>${state.tasks.filter(t=>state.notes.some(n=>n.id===t.note&&!n.deletedAt)).map(t=>link(esc(t.text),`${t.done?'Completed':'Due '+t.due} · ${find(t.target).name}`,`data-task="${t.id}"`,'calendar-check')).join('')||'<p class="day-muted">No accepted follow-ups.</p>'}`;
 }
 function review(){
  const n=state.notes.find(x=>x.id===state.reviewing);if(!n)return activity();
  return `${backrow()}<span class="day-kicker">Conversation</span><h1>${esc(conversationTitle(n))}</h1><p class="day-muted">${n.outcome} · ${n.meetingDate||dayLabel(n.day)} · ${n.language||'English'}</p><p class="day-caption" data-device-status>${esc(storageLabel())}</p>${n.deletedAt?`<p class="day-notice">In Trash. Restore it or remove this conversation and its media from this device.</p><div class="day-actions">${button('Restore',`data-restore-note="${n.id}"`,'primary')}${button('Delete permanently',`data-erase-note="${n.id}"`)}</div>`:`<div class="day-prep-section"><h2>Summary & next steps</h2><p>${esc(n.summary||processingLabel(n))}</p>${n.summaryStale?'<p class="day-caption">Transcript changed. Regenerate the summary before relying on it.</p>'+button('Regenerate demo summary',`data-retry-processing="${n.id}"`):''}${n.processing==='failed'?button('Retry processing',`data-retry-processing="${n.id}"`,'primary'):''}${n.suggestions?.filter(s=>!s.dismissed).map(s=>`<div class="day-material"><span>${esc(s.text)}</span><span class="day-caption">Demo suggestion · ${s.accepted?'Accepted':'Not a commitment yet'}</span>${!s.accepted?`<label class="day-field" for="suggestion-due-${el.dataset.layout}-${s.id}">Confirm due date</label><input class="day-input" type="date" id="suggestion-due-${el.dataset.layout}-${s.id}" data-suggestion-date="${s.id}" value="${s.proposedDue||''}"><div class="day-actions">${button('Accept follow-up',`data-accept-suggestion="${s.id}"`)}${button('Dismiss',`data-dismiss-suggestion="${s.id}"`)}</div>`:''}</div>`).join('')||''}</div>${n.originalAudioIds?.map(id=>`<div class="day-material"><audio controls preload="none" data-audio-asset="${id}"></audio>${button('Download original',`data-download-asset="${id}"`,'link')}</div>`).join('')||''}<details class="day-capture-context"><summary>Transcript & original input</summary>${n.transcriptIsMock?'<p class="day-notice">Demo transcript from a fixture. It is not a transcription of your recording.</p>':''}<p class="day-history-preview">${esc(n.correctedTranscript??n.transcriptOriginal??n.originalText??'No text available yet.')}</p><details><summary>Edit transcript</summary><label class="day-field" for="corrected-${el.dataset.layout}">Corrected transcript / note</label><textarea class="day-input" id="corrected-${el.dataset.layout}" data-corrected-transcript>${esc(n.pendingCorrection??n.correctedTranscript??n.transcriptOriginal??n.originalText??'')}</textarea>${button('Save correction','data-save-correction','primary')}</details><details class="day-capture-context"><summary>Original text · preserved</summary><p class="day-history-preview">${esc(n.transcriptOriginal||n.originalText||'No original text. See source audio below.')}</p></details>${n.originalFileIds?.map(id=>button('Download original file',`data-download-asset="${id}"`,'link')).join('')||''}</details><div class="day-actions">${button('Edit outcome or note',`data-edit-conversation="${n.id}"`)}<details class="day-more"><summary>Conversation options</summary>${button('Move to Trash',`data-trash-note="${n.id}"`,'link')}</details></div>`}${state.captureError?`<p class="day-notice" role="alert">${esc(state.captureError)}</p>`:''}`;
 }
 function sync(){return `${backrow()}<h1>Saved work</h1><p role="status" class="day-notice" data-device-status>${esc(storageLabel())}</p><div class="day-pair"><span>Drafts on this device</span><b>${Object.keys(state.drafts).length}</b></div><div class="day-pair"><span>Queued / processing</span><b>${state.notes.filter(n=>!n.deletedAt&&n.job).length}</b></div><div class="day-pair"><span>Cloud service</span><b>Mock adapter only</b></div><p class="day-caption day-section-heading">${deviceStore.persistent?'Local work survives refresh on this browser.':'This embedded preview uses memory only; refresh clears work. Open the published demo for durable local storage.'} It is not cloud backup or cross-device sync.</p><div class="day-actions">${button('Retry device save','data-retry-device-save','primary')}${button(state.scenario==='offline'?'Return online':'Go offline','data-local-offline')}${button('Review activity','data-nav="activity"')}</div>${link('CRM availability','No real CRM push is enabled.','data-open="crm"','refresh-cw')}`}
 function saveNote(){void logOutcome(activeDraft()?.outcome)}
 async function hydrateAudio(){
  for(const audio of el.querySelectorAll('[data-audio-asset]')){
   const id=audio.dataset.audioAsset;
   try{const meta=await deviceStore.asset(workspaceKey(),id);if(meta?.status==='interrupted'){const hint=document.createElement('p');hint.className='day-caption';hint.textContent='Recovered partial recording · Saved portions only';audio.before(hint)}if(meta?.mime.startsWith('text/')){audio.replaceWith(document.createTextNode(meta.name));continue}const blob=await recorder.blob(workspaceKey(),id);if(!audio.isConnected)return;const url=URL.createObjectURL(blob);audio.src=url;audio.dataset.objectUrl=url;audio.onemptied=()=>URL.revokeObjectURL(url)}catch(error){if(audio.isConnected){const message=document.createElement('p');message.className='day-caption';message.textContent=error.message;audio.replaceWith(message)}}
  }
 }
 async function startRecording(kind){
  const d=activeDraft();if(!d)return;state.captureError='';
  try{
   const id=Model.id();d.mediaIds.push(id);d.audioIds.push(id);await persistWork();
   await recorder.start({scope:workspaceKey(),id,draftId:d.id,kind,deny:state.scenario==='microphone-denied'});
   await persistWork();render();
  }catch(error){for(const id of [...d.mediaIds]){if(!await deviceStore.asset(workspaceKey(),id)){d.mediaIds=d.mediaIds.filter(x=>x!==id);d.audioIds=d.audioIds.filter(x=>x!==id)}}state.captureError=error.message;void persistWork().catch(()=>{});render()}
 }
 async function stopRecording(){try{await recorder.stop();await persistWork();state.captureError='';render()}catch(error){state.captureError=error.message;render()}}
 async function tickMockJobs(){if(runtimeBusy||restoring)return;runtimeBusy=true;try{if(Model.mockTick(state)){await persistWork();const visible=apps.find(a=>!a.el.closest('[data-variant]')?.hidden);if(visible&&['activity','review','prep','booking'].includes(state.page)&&!(visible.el.contains(document.activeElement)&&document.activeElement.matches('input,textarea,select')))visible.render()}}catch{}finally{runtimeBusy=false}}
 async function switchWorkspace(repId){
  if(['recording','interrupted','save-failed'].includes(recorder.current()?.status))await recorder.stop();await persistenceQueue.catch(()=>{});
  const next={companyId:'demo-company',repId},scope=Model.scopeKey(next),saved=await deviceStore.load(scope);
  Object.assign(state,saved||Model.clone(initialState));state.workspace=next;try{localStorage.setItem('field-pro-demo-active-rep',repId)}catch{};state.page='today';state.nav='today';state.history=[];state.notice='Switched sample workspace. Local records are isolated.';state.storageError='';render();await persistWork();
 }
 function bindCaptureUI(){
  el.querySelectorAll('[data-capture]').forEach(b=>b.onclick=()=>beginCapture(b.dataset.capture,b.dataset.draft,b.dataset.captureVisit));
  el.querySelectorAll('[data-log-outcome]').forEach(b=>b.onclick=()=>void logOutcome(b.dataset.logOutcome));
  const d=activeDraft();
  for(const [selector,key] of [['data-capture-note','note'],['data-capture-follow','follow'],['data-capture-due','due'],['data-capture-language','language'],['data-capture-follow-target','followTarget']]){
   const field=el.querySelector('['+selector+']');if(field)field.oninput=()=>{d[key]=field.value;d.updatedAt=Date.now();void persistWork().catch(()=>{})};
  }
  el.querySelectorAll('[data-capture-attendee]').forEach(b=>b.onchange=()=>{d.attendees=b.checked?[...new Set([...d.attendees,b.dataset.captureAttendee])]:d.attendees.filter(x=>x!==b.dataset.captureAttendee);void persistWork().catch(()=>{})});
  el.querySelector('[data-capture-voice]')?.addEventListener('click',()=>{d.showVoice=true;d.intent='voice';render();remember()});
  el.querySelector('[data-capture-intent]')?.addEventListener('change',e=>{d.intent=e.target.value;render();remember()});
  el.querySelectorAll('[data-record-start]').forEach(b=>b.onclick=()=>void startRecording(b.dataset.recordStart));
  el.querySelector('[data-record-stop]')?.addEventListener('click',()=>void stopRecording());
  el.querySelector('[data-record-interrupt]')?.addEventListener('click',()=>{recorder.interrupt('Demo interruption · Saved portions remain available.');render()});
  el.querySelector('[data-record-retry]')?.addEventListener('click',()=>void recorder.retry?.().then(()=>render()).catch(error=>{state.captureError=error.message;render()}));
  el.querySelector('[data-open-file]')?.addEventListener('click',()=>el.querySelector('[data-capture-file]').click());
  el.querySelector('[data-capture-file]')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(state.scenario==='storage-full')throw new Error('Device storage is full. Keep the original file.');if(file.size>100*1024*1024)throw new Error('This demo accepts files up to 100 MB. Keep the original file and add a shorter clip.');if(!/^(audio|video)\/|^text\/plain$/.test(file.type)&&!file.name.endsWith('.txt'))throw new Error('Choose an audio, video or plain-text transcript file.');const id=Model.id();await deviceStore.putFile(workspaceKey(),id,file);d.mediaIds.push(id);if(file.type.startsWith('audio/')||file.type.startsWith('video/'))d.audioIds.push(id);else d.fileIds.push(id);if(file.type==='text/plain'||file.name.endsWith('.txt'))d.note=await file.text();await persistWork();render()}catch(error){state.captureError=error.message;render()}});
  el.querySelectorAll('[data-download-asset]').forEach(b=>b.onclick=async()=>{try{const blob=await recorder.blob(workspaceKey(),b.dataset.downloadAsset),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;const meta=await deviceStore.asset(workspaceKey(),b.dataset.downloadAsset);a.download=meta?.name?.includes('.')?meta.name:'field-pro-original.'+(blob.type.includes('wav')?'wav':blob.type.includes('mp4')?'m4a':'webm');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error){state.captureError=error.message;render()}});
  const query=el.querySelector('[data-conversation-query]');if(query)query.oninput=()=>{state.activityQuery=query.value;const position=query.selectionStart;render();const q=el.querySelector('[data-conversation-query]');q.focus();q.setSelectionRange(position,position)};
  el.querySelectorAll('[data-activity-filter]').forEach(b=>b.onclick=()=>{state.activityFilter=b.dataset.activityFilter;render();remember()});
  el.querySelector('[data-corrected-transcript]')?.addEventListener('input',e=>{state.notes.find(x=>x.id===state.reviewing).pendingCorrection=e.target.value;void persistWork().catch(()=>{})});
  el.querySelector('[data-save-correction]')?.addEventListener('click',async()=>{const n=state.notes.find(x=>x.id===state.reviewing);n.correctedTranscript=el.querySelector('[data-corrected-transcript]').value;delete n.pendingCorrection;n.summaryStale=!!n.summary;await persistWork().catch(()=>{});render()});
  el.querySelectorAll('[data-edit-conversation]').forEach(b=>b.onclick=()=>{const n=state.notes.find(x=>x.id===b.dataset.editConversation),draft=Model.makeDraft({source:n.source,attendees:n.attendees,visitId:n.visitId,day:n.day});const task=state.tasks.find(t=>t.note===n.id&&t.manual);Object.assign(draft,{follow:task?.text||'',due:task?.due||'2026-10-18',followTarget:task?.target||n.target,editingNote:n.id,note:n.correctedTranscript??n.text??'',mediaIds:[...(n.originalAudioIds||[]),...(n.originalFileIds||[])],audioIds:[...(n.originalAudioIds||[])],fileIds:[...(n.originalFileIds||[])]});state.drafts[draft.id]=draft;beginCapture(n.source,draft.id)});
  el.querySelectorAll('[data-retry-processing]').forEach(b=>b.onclick=()=>{Model.retry(state.notes.find(n=>n.id===b.dataset.retryProcessing));render();remember()});
  el.querySelectorAll('[data-accept-suggestion]').forEach(b=>b.onclick=()=>{try{Model.acceptSuggestion(state,state.reviewing,b.dataset.acceptSuggestion,el.querySelector('[data-suggestion-date="'+b.dataset.acceptSuggestion+'"]').value);state.captureError='';render();remember()}catch(error){state.captureError=error.message;render()}});
  el.querySelectorAll('[data-dismiss-suggestion]').forEach(b=>b.onclick=()=>{state.notes.find(n=>n.id===state.reviewing).suggestions.find(s=>s.id===b.dataset.dismissSuggestion).dismissed=true;render();remember()});
  el.querySelectorAll('[data-trash-note]').forEach(b=>b.onclick=()=>{Model.trash(state,b.dataset.trashNote);state.page='activity';state.activityFilter='all';state.lastUndo=null;render();remember()});
  el.querySelectorAll('[data-restore-note]').forEach(b=>b.onclick=()=>{Model.restore(state,b.dataset.restoreNote);state.activityFilter='all';render();remember()});
  el.querySelectorAll('[data-erase-note]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this conversation, linked follow-ups and source media from this device? This cannot be undone.'))return;const before=Model.clone(state),assets=Model.erase(state,b.dataset.eraseNote);try{await persistenceQueue.catch(()=>{});await deviceStore.deleteBundle(workspaceKey(),state,assets);state.page='activity';render()}catch(error){Object.assign(state,before);state.captureError=error.message;render()}});
  el.querySelector('[data-undo-outcome]')?.addEventListener('click',()=>{const undo=state.lastUndo;if(!undo)return;state.notes=state.notes.filter(n=>n.id!==undo.noteId);state.tasks=state.tasks.filter(t=>t.note!==undo.noteId);state.drafts[undo.draft.id]=undo.draft;if(undo.previousVisit){const i=state.items.findIndex(x=>x.id===undo.previousVisit.id);if(i>=0)state.items[i]=undo.previousVisit}state.lastUndo=null;state.notice='Outcome undone. Your draft is available.';render();remember()});
  el.querySelector('[data-retry-device-save]')?.addEventListener('click',()=>void persistWork().then(()=>render()).catch(()=>render()));
  el.querySelector('[data-local-offline]')?.addEventListener('click',()=>{state.scenario=state.scenario==='offline'?'normal':'offline';render();remember()});
  el.querySelectorAll('[data-switch-workspace]').forEach(b=>b.onclick=()=>void switchWorkspace(b.dataset.switchWorkspace));
  void hydrateAudio();
 }

