window.addEventListener('field-pro:preview-layout',e=>{
 const from=apps.find(a=>a.el.closest('[data-variant]')?.dataset.variant===e.detail?.from);
 const to=apps.find(a=>a.el.closest('[data-variant]')?.dataset.variant===e.detail?.to);
 if(!from||!to||from===to)return;
 Object.assign(to.state,structuredClone(from.state));
 Object.assign(to.cfg,{offline:from.cfg.offline,mapPreview:from.cfg.mapPreview});
 to.render();
});
async function bootDeviceState(){
 try{try{const selected=localStorage.getItem('field-pro-demo-active-rep');if(['demo-rep','demo-rep-2'].includes(selected))sharedState.workspace.repId=selected}catch{}const stored=await deviceStore.load(Model.scopeKey(sharedState.workspace));if(stored?.version===10)Object.assign(sharedState,stored);sharedState.storageError='';sharedState.storageStatus='saved';
 for(const d of Object.values(sharedState.drafts)){for(const id of d.mediaIds){const asset=await deviceStore.asset(Model.scopeKey(sharedState.workspace),id);if(asset?.status==='recording')await deviceStore.finish(Model.scopeKey(sharedState.workspace),id,'interrupted')}}
 }catch(error){sharedState.storageError=error.message;sharedState.storageStatus='failed'}
 restoring=false;sharedState.captureBusy=false;root.inert=false;apps.forEach(a=>a.render());
}
root.inert=true;void bootDeviceState();
setInterval(()=>{const a=apps.find(a=>!a.el.closest('[data-variant]')?.hidden)||apps[0];if(a)void a.tickMockJobs()},400);
window.addEventListener('pagehide',()=>recorder.interrupt('Page closed. Recover the last committed audio portions.'));
window.addEventListener('field-pro:scenario',e=>{sharedState.scenario=e.detail.scenario;const a=apps.find(a=>!a.el.closest('[data-variant]')?.hidden)||apps[0];a.render();void a.persistWork().catch(()=>{})});
window.addEventListener('field-pro:reset',async()=>{restoring=true;recorder.interrupt();await recorder.drain().catch(()=>{});recorder.dispose();await persistenceQueue.catch(()=>{});await deviceStore.clear(Model.scopeKey(sharedState.workspace));location.reload()});
window.addEventListener('field-pro:booking-cancel',()=>{const i=sharedState.items.find(i=>i.bookingStatus==='confirmed'&&i.requestId&&!i.cancelled);if(i){Model.applyBookingEvent(sharedState,{visitId:i.id,requestId:i.requestId,id:Model.id(),version:(i.providerVersion||0)+1,status:'cancelled'});sharedState.page='today';sharedState.nav='today';apps.forEach(a=>a.render());void apps[0].persistWork().catch(()=>{})}});
window.addEventListener('openai:set_globals',e=>{const s=e.detail?.globals?.widgetState;if(s?.privateContent?.version!==7)return;apps.forEach(a=>{if(a.el.dataset.layout===s.modelContent?.layout&&s.privateContent.design){Object.assign(a.cfg,s.privateContent.design);a.render()}})});
